func TestCreateMessageRefOverridesDerivedPubsub(t *testing.T) {
	// The loader template's shape: spec.values derives pubsub as a platform
	// convention. That convention declares no intent about this message, so
	// the registry's channel overrides it — with a note, not an error.
	lib := newTestLibrary(t, "v1.0.0", map[string]string{
		"subscriber/template.yaml": subscriberTemplateYAML + `  values:
    pubsub: 'pubsub'
`,
		"subscriber/skeleton/wiring.txt.tmpl": "pubsub={{ .pubsub }}\n",
	})
	registry := messageRegistryServer(t)
	outDir := filepath.Join(t.TempDir(), "out")
	var stderr bytes.Buffer

	err := Create(context.Background(), CreateOptions{
		Template:  "subscriber",
		OutputDir: outDir,
		Version:   "v1.0.0",
		SetValues: map[string]any{
			"name":         "loader",
			"subscription": "/messagegroups/io.intropy.maxbo.product/messages/io.intropy.maxbo.product.export",
		},
		NoInput:     true,
		Stderr:      &stderr,
		Source:      lib.sourceOpts(t.TempDir(), nil),
		RegistryURL: registry.URL,
	})
	if err != nil {
		t.Fatalf("a derived value must not conflict with the registry: %v", err)
	}
	rendered, err := os.ReadFile(filepath.Join(outDir, "wiring.txt"))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(rendered), "pubsub=product-distribution-pubsub") {
		t.Errorf("registry channel should win, got %q", rendered)
	}
	if !strings.Contains(stderr.String(), `pubsub: product-distribution-pubsub (from the message registry; was "pubsub")`) {
		t.Errorf("override should be noted, got %q", stderr.String())
	}
}

