// Package web embeds the Intropy dashboard SPA so the CLI can serve it
// without any runtime dependency on Node or a Vite dev server.
//
// Two trees are embedded and one is picked at serve time: placeholder/dist,
// committed, and dist, the `vite build` output (see `make web`), which is
// gitignored and present only in a workspace where the SPA has been built.
// Embed patterns must match at compile time, so an unbuilt workspace
// keeps a marker file in dist (restored by `make web-clean`). A built dist
// drops the marker, and its absence is what makes the real SPA win — the
// state released binaries ship.
package web

import (
	"embed"
	"io/fs"
)

//go:embed all:placeholder/dist all:dist
var embedded embed.FS

// Assets is the embedded SPA tree, holding index.html at its root with any
// hashed JS/CSS bundles under assets/. It is the real `vite build` output
// when the binary was compiled after `make web`, and the committed
// placeholder otherwise.
var Assets = pick()

func pick() fs.FS {
	// dist/index.html exists in both states, so presence alone does not
	// discriminate; the marker does. See placeholder/dist/index.html.
	if _, err := fs.Stat(embedded, "dist/placeholder.html"); err != nil {

import type { TemplateField } from '../api'

// The template-form controls shared by every create surface (the flow
// view's create drawer, the seed drawer): one schema parameter rendered as
// the matching input, and the label + control row it sits in.

// FormField renders one schema parameter as the matching input: a combobox
// for an enum, a checkbox for a boolean, a number input for integer/number,
// a text input otherwise. Pattern and required come straight from the schema.
export function FormField({
  field,
  value,
  onChange,
}: {
  field: TemplateField
  value: unknown
  onChange: (key: string, v: unknown) => void
}) {
  const set = (v: unknown) => onChange(field.name, v)

  let input: React.ReactNode
  if (field.type === 'boolean') {
    input = (
      <input
        type="checkbox"
        checked={Boolean(value)}
        onChange={(e) => set(e.target.checked)}
      />
    )
  } else if (field.enum && field.enum.length > 0) {
    input = (
      <select
        value={value === undefined ? '' : String(value)}
        onChange={(e) => set(e.target.value || undefined)}
      >
        <option value="">—</option>
        {field.enum.map((opt) => (
          <option key={String(opt)} value={String(opt)}>
            {String(opt)}
          </option>
        ))}
      </select>
    )
  } else if (field.suggestions && field.suggestions.length > 0) {
    // Workspace candidates ride a datalist: the input stays free text
    // (a scaffold may deliberately declare a new topic) while the known
    // values are one arrow-key away. A select would close the list; the
    // CLI prompt's pick-list-plus-freetext is the parity target.
    const listId = `suggestions-${field.name}`
    input = (
      <>
        <input
          type="text"
          value={value === undefined ? '' : String(value)}
          pattern={field.pattern || undefined}
          list={listId}
          onChange={(e) => set(e.target.value === '' ? undefined : e.target.value)}
        />
        <datalist id={listId}>
          {field.suggestions.map((s) => (
            <option key={s} value={s} />
          ))}
        </datalist>
      </>
    )
  } else if (field.type === 'integer' || field.type === 'number') {
    input = (
      <input
        type="number"
        value={value === undefined ? '' : String(value)}
        step={field.type === 'integer' ? 1 : 'any'}
        onChange={(e) => set(e.target.value === '' ? undefined : Number(e.target.value))}
      />
    )
  } else {
    input = (
      <input
        type="text"
        value={value === undefined ? '' : String(value)}
        pattern={field.pattern || undefined}
        onChange={(e) => set(e.target.value === '' ? undefined : e.target.value)}
      />
    )
  }

  return (
    <Field
      label={field.name}
      title={field.title}
      description={field.description}
      required={field.required}
      type={field.type}
    >
      {input}
    </Field>
  )
}

// Field is the label + control row every parameter renders through, with the
// same required marker `template show` prints.
