// validateMessageRefParams rejects a message-ref annotation on a parameter
// whose type is not "string". The reference is a message id or xid — a
// string — and a boolean or number carrying the annotation is an authoring
// mistake best reported where the manifest is loaded.
func validateMessageRefParams(params map[string]any) error {
	props, _ := params["properties"].(map[string]any)
	for name, raw := range props {
		schema, _ := raw.(map[string]any)
		ref, _ := schema[MessageRefExtension].(bool)
		if !ref {
			continue
		}
		if typ, _ := schema["type"].(string); typ != "string" {
			return fmt.Errorf("spec.parameters.properties.%s: %s requires type \"string\", got %q", name, MessageRefExtension, typ)
		}
	}
	return nil
}

func validateBindingCatalog(path string, bindings []string) error {
	seen := make(map[string]bool, len(bindings))
	for i, binding := range bindings {
		if !fixtureNamePattern.MatchString(binding) {
			return fmt.Errorf("%s[%d]: %q is not a valid binding name (lowercase letters, digits and dashes, starting with a letter or digit)", path, i, binding)
		}
		if seen[binding] {
			return fmt.Errorf("%s[%d]: %q is declared twice", path, i, binding)
		}
		seen[binding] = true
	}
	return nil
}

