func TestLoadTemplateMessageRefAnnotation(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, templateManifestName)
	body := `
apiVersion: intropy.dev/v1
kind: Template
metadata:
  name: subscriber
spec:
  parameters:
    type: object
    required: [subscription]
    properties:
      subscription:
        type: string
        title: Message
        description: Message to subscribe to
        x-intropy-message-ref: true
      name:
        type: string
      retries:
        type: integer
        x-unrelated-extension: whatever
`
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
	tmpl, err := LoadTemplate(path)
	if err != nil {
		t.Fatalf("LoadTemplate: %v", err)
	}
	fields := tmpl.Fields()
	if len(fields) != 3 {
		t.Fatalf("Fields = %d, want 3", len(fields))
	}
	if !fields[0].MessageRef {
		t.Errorf("subscription field should be a message ref: %+v", fields[0])
	}
	if fields[1].MessageRef || fields[2].MessageRef {
		t.Errorf("unannotated fields should not be message refs: %+v / %+v", fields[1], fields[2])
	}
	// Unrelated extension keys are ignored, not an error — that is what
	// keeps annotated manifests loadable by older CLIs and JSON Schema
	// tooling.
}

func TestLoadTemplateRejectsMessageRefOnNonString(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, templateManifestName)
	body := `
apiVersion: intropy.dev/v1
kind: Template
metadata:
  name: subscriber
spec:
  parameters:
    type: object
    properties:
      subscription:
        type: boolean
        x-intropy-message-ref: true
`
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
	_, err := LoadTemplate(path)
	if err == nil {
		t.Fatal("expected a validation error")
	}
	if got := err.Error(); !strings.Contains(got, "subscription") || !strings.Contains(got, MessageRefExtension) {
		t.Errorf("error should name the parameter and the extension key, got %q", got)
	}
}

