package dashboard

// Temporary live-UI check server: serves the real dashboard on :8732 with
// the actual loader manifest from the local intropy-templates working tree
// and the developer's registry at :8787, so a browser can exercise the
// derived-wiring form. Deleted after the check — not committed.

import (
	"net"
	"net/http"
	"os"
	"testing"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/template/templatetest"
)

func TestLiveCheckServer(t *testing.T) {
	if os.Getenv("LIVECHECK") == "" {
		t.Skip("set LIVECHECK=1 to run the live check server")
	}
	loader, err := os.ReadFile(os.Getenv("LIVECHECK_LOADER"))
	if err != nil {
		t.Fatal(err)
	}
	lib := templatetest.NewLibrary(t, "v9", map[string]string{
		"loader/template.yaml":         string(loader),
		"loader/skeleton/README.md.tmpl": "# {{ .name }}\n",
	})
	h, api, err := newHandler(t.TempDir(), "dev", templateProviders(lib.Source(t)))
	if err != nil {
		t.Fatal(err)
	}
	api.registryURL = "http://127.0.0.1:8787"
	ln, err := net.Listen("tcp", "127.0.0.1:8732")
	if err != nil {
		t.Fatal(err)
	}
	t.Log("live check on http://127.0.0.1:8732")
	go func() { _ = http.Serve(ln, h) }()
	time.Sleep(5 * time.Minute)
}

